css:
.chapter-scope {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #003366;
  --warm: #ff6b35;
  --line: #e0e0e0;
  --paper: #f9f9f9;

  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--ink);
  line-height: 1.6;
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

.chapter-header {
  margin-bottom: 3rem;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
}

.chapter-header h1 {
  font-size: 2.5rem;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.lead {
  font-size: 1.2rem;
  color: var(--muted);
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.narrative-block {
  background: var(--paper);
  padding: 1.5rem;
  border-left: 4px solid var(--accent);
}

.narrative-block h2 {
  color: var(--accent);
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.narrative-block p {
  margin-bottom: 1rem;
  font-size: 1rem;
}

.source-actions {
  margin-top: 1.5rem;
}

.btn-source {
  background: var(--accent);
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  margin-right: 0.5rem;
  cursor: pointer;
  font-size: 0.9rem;
}

.btn-source:hover {
  background: #002244;
}

.interactive-panel {
  background: var(--paper);
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.panel-header h3 {
  color: var(--warm);
  margin-bottom: 0.5rem;
}

.panel-desc {
  color: var(--muted);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

.control-group {
  margin-bottom: 1.5rem;
}

.control-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.highlight {
  color: var(--warm);
  font-weight: 700;
}

input[type="range"] {
  width: 100%;
  height: 8px;
  background: var(--line);
  border-radius: 4px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  width: 20px;
  height: 20px;
  background: var(--accent);
  border-radius: 50%;
  cursor: pointer;
}

.result-display {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.metric-card {
  background: white;
  padding: 1rem;
  text-align: center;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.metric-label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
}

.metric-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.metric-status {
  display: block;
  font-size: 1rem;
  font-weight: 600;
}

.status-ok {
  color: #28a745;
}

.status-warning {
  color: #ffc107;
}

.status-impossible {
  color: #dc3545;
}

.explanation-box {
  background: white;
  padding: 1rem;
  border-left: 3px solid var(--warm);
  font-size: 0.9rem;
}

.full-width {
  grid-column: 1 / -1;
}

javascript:
(function() {
  const slider = document.getElementById('var-count-slider');
  const countDisplay = document.getElementById('var-count-display');
  const comboCount = document.getElementById('combo-count');
  const feasibilityStatus = document.getElementById('feasibility-status');
  const explanationText = document.getElementById('explanation-text');

  // 每个变量平均有 2 个选项（如男/女，老/少）
  const optionsPerVar = 2;

  function updateDisplay() {
    const n = parseInt(slider.value);
    const combinations = Math.pow(optionsPerVar, n);

    countDisplay.textContent = n;
    comboCount.textContent = combinations.toLocaleString();

    // 更新可行性状态
    if (n <= 4) {
      feasibilityStatus.textContent = '可行';
      feasibilityStatus.className = 'metric-status status-ok';
      explanationText.textContent = '当变量较少时，场景数量有限，传统调查方法可以覆盖所有组合。';
    } else if (n <= 6) {
      feasibilityStatus.textContent = '困难';
      feasibilityStatus.className = 'metric-status status-warning';
      explanationText.textContent = '随着变量增加，场景数量快速增长，传统调查开始面临样本量不足的挑战。';
    } else {
      feasibilityStatus.textContent = '不可行';
      feasibilityStatus.className = 'metric-status status-impossible';
      explanationText.textContent = '当变量达到 9 个时，场景组合数达到数百万种，远超传统数据收集方法的能力，必须采用大规模在线实验。';
    }
  }

  slider.addEventListener('input', updateDisplay);
  updateDisplay();
})();
